public static int readUShortLE(InputStream stream) throws IOException, BufferUnderrunException {
    int ch1 = stream.read();
    int ch2 = stream.read();
    if ((ch1 | ch2) < 0) {
        throw new BufferUnderrunException();
    }
    return (ch2 << 8) + (ch1);
}
